sys_variable_value.value:
(function (outputs, steps, params, stepResult, assertEqual) {
    function deptByCode(code) {
        var d = new GlideRecord('cmn_department');
        d.addQuery('id', code);
        d.query();
        return d.next() ? d.getUniqueValue() : '';
    }
    function userByName(name) {
        var u = new GlideRecord('sys_user');
        u.addQuery('user_name', name);
        u.query();
        return u.next() ? u.getUniqueValue() : '';
    }
    function groupByName(name) {
        var g = new GlideRecord('sys_user_group');
        g.addQuery('name', name);
        g.query();
        return g.next() ? g.getUniqueValue() : '';
    }

    var resolver = new ITFRoutingResolver();

    describe('ITFRoutingResolver', function () {
        it('has its decision table sys_id published in the dt_department_routing property', function () {
            expect(gs.getProperty('x_snc_sas_positi_0.dt_department_routing')).toBeTruthy();
        });

        it('routes Commerce to its own director, analyst and group', function () {
            var r = resolver.resolve(deptByCode('COM'));
            expect(r.error).toBe('');
            expect(r.director).toBe(userByName('itf.demo.director'));
            expect(r.analyst).toBe(userByName('itf.demo.analyst'));
            expect(r.group).toBe(groupByName('OPM Analysts'));
        });

        it('routes Health to the leadership analyst and group', function () {
            var r = resolver.resolve(deptByCode('HEALTH'));
            expect(r.error).toBe('');
            expect(r.director).toBe(userByName('itf.demo.director'));
            expect(r.analyst).toBe(userByName('itf.demo.leadership'));
            expect(r.group).toBe(groupByName('OPM Hiring Freeze Leadership'));
        });

        it('routes Shared Administrative Services to the admin director and ITF Administrators', function () {
            var r = resolver.resolve(deptByCode('DSAS'));
            expect(r.error).toBe('');
            expect(r.director).toBe(userByName('itf.demo.admin'));
            expect(r.analyst).toBe(userByName('itf.demo.analyst'));
            expect(r.group).toBe(groupByName('ITF Administrators'));
        });

        it('returns an error rather than a wrong answer for an unmapped department', function () {
            var r = resolver.resolve('0000000000000000000000000000dead');
            expect(r.director).toBe('');
            expect(r.analyst).toBe('');
            expect(r.group).toBe('');
            expect(r.error).not.toBe('');
        });
    });
})(outputs, steps, params, stepResult, assertEqual);
jasmine.getEnv().execute();
